head.script:
scwin.screenId = "jldbnf50100";

///////// 1. 변수 및 선언 영역 /////////

scwin.dmenus = undefined;

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.fm = undefined;


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("saleInstNm")))); } },
        { childId: "__rb1", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("saleIsuNm")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_datefmt_cal_efReqStartDt
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_datefmt_cal_efReqStartDt = function () { $c.date.checkCalendarFormat("cal_efReqStartDt", "yyyyMMdd"); };

/**
 * @method
 * @name scwin.init_datefmt_cal_efReqEndDt
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_datefmt_cal_efReqEndDt = function () { $c.date.checkCalendarFormat("cal_efReqEndDt", "yyyyMMdd"); };

/**
 * @method
 * @name scwin.initPageIndex
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.initPageIndex = function () {
    /* sdd-asis-lifecycle:begin initPageIndex — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_searchListReq').set('pageIndex', "1");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.dmenus = { "bmenu": 1, "mmenu": 0 };
        $('div#header').trigger('mouseleave');
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf50100.onpageload' }); }
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 4개다(tx_fn_searchList, tx_OpenReqView, tx_OpenRetView, tx_PopUp_FeeCal) — 어느 것이 «열자마자» 인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_datefmt_cal_efReqStartDt();
        scwin.init_datefmt_cal_efReqEndDt();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf50100.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
