/**
 * @event
 * @name scwin.grd_result_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_result_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_result'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["applYn"] === '반송') { if (typeof scwin.OpenRetView === 'function') { await scwin.OpenRetView(r["bndApplId"], r["bndListProcsTpCd"], r["bndMktactTpCd"], r["bkbndTpCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.OpenRetView (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.OpenRetView'); } return; }
        if (typeof scwin.OpenReqView === 'function') { await scwin.OpenReqView(r["bndApplId"], "1", "320", ""); } else { console.error('[sdd] 행 동작 미정의: scwin.OpenReqView (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.OpenReqView'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_searchList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "/sales/sales.do",
        ref: "dma_searchListReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf50100.tx_fn_searchList" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

