    /* sdd-asis-lifecycle:begin fn_searchList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.SearchForm || { elements: [] });
    $c.util.getComponent('dma_searchListReq').set('method', "salesReportRstList");
    frm.action = '/sales/sales.do';
    frm.target = '_self';
    await scwin.tx_fn_searchList();
    /* sdd-asis-lifecycle:end */
};


/**
